import time
import random
from enum import Enum

class Ability(Enum):
    STRENGTH = "Strength"
    AGILITY = "Agility"
    INTELLIGENCE = "Intelligence"
    STEALTH = "Stealth"

class Environment(Enum):
    FOREST = "Forest"
    CAVE = "Cave"
    RUINS = "Ancient Ruins"
    FINAL_CHAMBER = "Final Treasure Chamber"

class PuzzleResult(Enum):
    SUCCESS = "Puzzle solved successfully"
    FAILURE = "Puzzle solution failed"
    NOT_READY = "Puzzle cannot be solved yet"

class Player:
    def __init__(self, name, team, ability):
        self.name = name
        self.team = team
        self.ability = ability
        self.is_active = True

    def __str__(self):
        return f"Player: {self.name}, Team: {self.team}, Ability: {self.ability.value}"

class Team:
    def __init__(self, name):
        self.name = name
        self.players = []
        self.treasures_collected = 0
        self.completed_puzzles = set()

    def add_player(self, player):
        if len(self.players) < 4:
            self.players.append(player)
            return True
        return False

    def total_ability(self, ability):
        return sum(1 for p in self.players if p.ability == ability and p.is_active)

    def __str__(self):
        return f"Team: {self.name}, Players: {len(self.players)}, Treasures: {self.treasures_collected}"

class GameEnvironment:
    def __init__(self, environment_type):
        self.type = environment_type
        self.treasures = 0
        self.puzzles = self._generate_puzzles()

    def _generate_puzzles(self):
        # Generate puzzles specific to each environment
        if self.type == Environment.FOREST:
            return [
                {"name": "Riddle of the Trees", "required_abilities": [Ability.INTELLIGENCE]},
                {"name": "Clear the Log", "required_abilities": [Ability.STRENGTH]}
            ]
        elif self.type == Environment.CAVE:
            return [
                {"name": "Solve the Lever Puzzle", "required_abilities": [Ability.INTELLIGENCE]},
                {"name": "Move the Boulders", "required_abilities": [Ability.STRENGTH]}
            ]
        elif self.type == Environment.RUINS:
            return [
                {"name": "Decipher the Ancient Script", "required_abilities": [Ability.INTELLIGENCE]},
                {"name": "Unlock the Vault", "required_abilities": [Ability.STRENGTH]}
            ]
        elif self.type == Environment.FINAL_CHAMBER:
            return [
                {"name": "Final Riddle", "required_abilities": [Ability.INTELLIGENCE, Ability.STRENGTH]}
            ]
        return []

    def _has_required_abilities(self, team):
        for puzzle in self.puzzles:
            required_abilities = puzzle["required_abilities"]
            for ability in required_abilities:
                if team.total_ability(ability) <= 0:
                    return False
        return True

    def attempt_puzzle(self, team, puzzle_name):
        if not self._has_required_abilities(team):
            return PuzzleResult.NOT_READY

        success_prob = 0.8
        if random.random() < success_prob:
            return PuzzleResult.SUCCESS
        return PuzzleResult.FAILURE

class GameEngine:
    def __init__(self):
        self.teams = []
        self.environments = []
        self.current_environment_index = 0
        self.start_time = None
        self.completed_teams = []

    def add_team(self, team):
        self.teams.append(team)

    def setup_environments(self):
        # Create a sequence of environments
        self.environments = [
            GameEnvironment(Environment.FOREST),
            GameEnvironment(Environment.CAVE),
            GameEnvironment(Environment.RUINS),
            GameEnvironment(Environment.FINAL_CHAMBER)
        ]

    def collect_treasure(self, team):
        # Teams collect treasures in each environment
        if self.current_environment_index < len(self.environments) - 1:
            team.treasures_collected += 1
            return True
        return False

    def check_all_puzzles_solved(self, team):
        # Check if all puzzles in current environment are solved
        environment = self.environments[self.current_environment_index]

        for puzzle in environment.puzzles:
            if puzzle["name"] not in team.completed_puzzles:
                return False
        return True

    def advance_environment(self, team):
        # Move to next environment if all puzzles are solved
        if (self.current_environment_index < len(self.environments) - 1 and 
            self.check_all_puzzles_solved(team)):
            self.current_environment_index += 1
            team.completed_puzzles = set()  # Reset puzzles for next environment
            return True
        return False

    def solve_puzzle(self, team, puzzle_name):
        # Try to solve a puzzle in the current environment
        environment = self.environments[self.current_environment_index]
        result = environment.attempt_puzzle(team, puzzle_name)

        if result == PuzzleResult.SUCCESS:
            team.completed_puzzles.add(puzzle_name)
            return True
        return False

    def start_game(self):
        self.start_time = time.time()
        print("Game started! Good luck to all teams!")

    def end_game(self):
        end_time = time.time()
        game_duration = end_time - self.start_time

        # Calculate scores
        scores = []
        for team in self.teams:
            # Score formula: (number of treasures x 100) - (duration in seconds x 10)
            score = team.treasures_collected * 100 - game_duration * 10
            scores.append((team.name, score))

        # Sort by score (descending)
        scores.sort(key=lambda x: x[1], reverse=True)

        print("\nGame Results:")
        for i, (team_name, score) in enumerate(scores):
            print(f"{i+1}. Team {team_name}: {score:.1f} points")

        # Determine winner
        if scores[0][1] > scores[1][1]:
            print(f"\nWinner: Team {scores[0][0]}!")
        else:
            print("\nIt's a tie!")

    def player_left(self, player):
        # Handle player leaving the game
        for team in self.teams:
            for p in team.players:
                if p.name == player.name:
                    p.is_active = False
                    print(f"{player.name} has left the game.")

    def get_game_state(self):
        # Return current game state for all teams
        state = []
        for team in self.teams:
            state.append({
                "team_name": team.name,
                "current_environment": self.environments[self.current_environment_index].type.value,
                "treasures_collected": team.treasures_collected,
                "puzzles_solved": list(team.completed_puzzles),
                "active_players": sum(1 for p in team.players if p.is_active)
            })
        return state

