class GameDatabase:
    """
    Simulated database layer for storing and retrieving game data.
    In a real-world application, this would interface with a proper database system.
    """
    def __init__(self):
        self.players = {}  # {player_id: {name, teams, scores, history}}
        self.teams = {}    # {team_id: {name, members, scores, challenges}}
        self.games = {}    # {game_id: {teams, progress, history}}
        self.lock = threading.Lock()

    def add_player(self, player_id, name):
        with self.lock:
            self.players[player_id] = {
                'name': name,
                'teams': [],
                'scores': 0,
                'history': []
            }

    def add_team(self, team_id, name, members):
        with self.lock:
            self.teams[team_id] = {
                'name': name,
                'members': members,
                'scores': 0,
                'challenges': []
            }

    def add_game(self, game_id, teams):
        with self.lock:
            self.games[game_id] = {
                'teams': teams,
                'progress': {},
                'history': []
            }

    def update_score(self, game_id, team_id, score):
        with self.lock:
            if game_id in self.games and team_id in self.games[game_id]['teams']:
                self.games[game_id]['progress'][team_id] = score

    def get_game_progress(self, game_id):
        with self.lock:
            return self.games.get(game_id, {}).get('progress', {})

    def get_player_score(self, player_id):
        with self.lock:
            return self.players.get(player_id, {}).get('scores', 0)

