class GameServer:
    """
    Game server to manage real-time communication and game state.
    """
    def __init__(self, host='localhost', port=12345):
        self.db = GameDatabase()
        self.host = host
        self.port = port
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.setblocking(False)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen()
        self.inputs = [self.server_socket]
        self.outputs = []
        self.message_queue = defaultdict(list)

    def run(self):
        print(f"Server started on {self.host}:{self.port}")
        while self.inputs:
            readable, writable, exceptional = select.select(self.inputs, self.outputs, self.inputs)
            for s in readable:
                if s is self.server_socket:
                    # New connection
                    client_socket, addr = s.accept()
                    print(f"New connection from {addr}")
                    client_socket.setblocking(False)
                    self.inputs.append(client_socket)
                    self.message_queue[client_socket] = []
                else:
                    # Data from client
                    data = s.recv(1024)
                    if data:
                        message = json.loads(data.decode('utf-8'))
                        self.message_queue[s].append(message)
                    else:
                        # Client disconnected
                        if s in self.outputs:
                            self.outputs.remove(s)
                        self.inputs.remove(s)
                        s.close()
                        del self.message_queue[s]

            for s in writable:
                if self.message_queue[s]:
                    message = self.message_queue[s].pop(0)
                    s.send(json.dumps(message).encode('utf-8'))

            for s in exceptional:
                print(f"Exception on {s}")
                self.inputs.remove(s)
                if s in self.outputs:
                    self.outputs.remove(s)
                s.close()
                del self.message_queue[s]

    def handle_message(self, message, client_socket):
        action = message.get('action')
        if action == 'join_game':
            game_id = message.get('game_id')
            player_id = message.get('player_id')
            team_id = message.get('team_id')
            if game_id in self.db.games and player_id in self.db.players and team_id in self.db.teams:
                self.db.games[game_id]['teams'][team_id].append(player_id)
                self.db.players[player_id]['teams'].append(game_id)
                self.message_queue[client_socket].append({
                    'status': 'success',
                    'message': f"Player {player_id} joined team {team_id} in game {game_id}."
                })
            else:
                self.message_queue[client_socket].append({
                    'status': 'error',
                    'message': 'Invalid game, team, or player ID.'
                })

        elif action == 'update_score':
            game_id = message.get('game_id')
            team_id = message.get('team_id')
            score = message.get('score')
            self.db.update_score(game_id, team_id, score)
            self.message_queue[client_socket].append({
                'status': 'success',
                'message': f"Score for team {team_id} in game {game_id} updated to {score}."
            })

        elif action == 'get_progress':
            game_id = message.get('game_id')
            progress = self.db.get_game_progress(game_id)
            self.message_queue[client_socket].append({
                'status': 'success',
                'message': 'Game progress retrieved.',
                'progress': progress
            })

