        self.users[user_id] = User(user_id, name, email, password)
        return 'User registered successfully'

    def create_budget(self, budget_id, name, owner_id, start_date, end_date):
        if budget_id in self.budgets:
            return 'Budget already exists'
        self.budgets[budget_id] = Budget(budget_id, name, owner_id, start_date, end_date)
        self.users[owner_id].add_budget(budget_id, 'admin')
        return 'Budget created successfully'

    def invite_user_to_budget(self, budget_id, user_id, access_level):
        if budget_id not in self.budgets:
            return 'Budget does not exist'
        if user_id not in self.users:
            return 'User does not exist'
        self.budgets[budget_id].add_user(user_id, access_level)
        self.users[user_id].add_budget(budget_id, access_level)
        self.notifications.send_notification(f'You have been invited to join the budget: {self.budgets[budget_id].name} with access level: {access_level}')
        return 'User invited successfully'

    def add_transaction_to_budget(self, budget_id, user_id, amount, category_id, date):
        if budget_id not in self.budgets:
            return 'Budget does not exist'
        if user_id not in self.users:
            return 'User does not exist'
        if self.budgets[budget_id].users.get(user_id) not in ['admin', 'edit']:
            return 'Insufficient permissions'
        transaction_id = len(self.budgets[budget_id].transactions) + 1
        self.budgets[budget_id].add_transaction(transaction_id, user_id, amount, category_id, date)
        self.notifications.send_notification(f'{self.users[user_id].name} added a transaction of ${amount} to category {category_id} in budget {budget_id}')
        return 'Transaction added successfully'

    def generate_dashboard(self, budget_id):
        if budget_id not in self.budgets:
            return 'Budget does not exist'
        dashboard = Dashboard(self.budgets[budget_id])
        dashboard.display_spending_breakdown()
        dashboard.display_budget_progress()
        return 'Dashboard generated successfully'

    def check_budget_goals(self):
        for budget in self.budgets.values():
            total_budget = sum(goal['target'] for goal in budget.goals)
            total_spent = sum(transaction['amount'] for transaction in budget.transactions)
            if total_spent >= total_budget * 0.9:
                self.notifications.send_notification(f'Warning: Budget {budget.name} is 90% or more spent.')

    def adapt_budget_based_on_income(self, user_id, new_income):
        user = self.users[user_id]
        user.personal_income = new_income
        for budget_id in user.budgets:
            budget = self.budgets[budget_id]
            total_spent = sum(transaction['amount'] for transaction in budget.transactions if transaction['user_id'] == user_id)
            if total_spent > 0.8 * new_income:
                self.notifications.send_notification(f'Your spending in budget {budget.name} exceeds 80% of your new income. Consider revising your budget.')

